(function(){
  var D=window.__I18N_DICT||{},L=window.APP_LANG||'pt';
  if(L==='pt')return;
  var LOC=L==='en'?'en-US':'es-ES';
  document.documentElement.lang=L==='en'?'en':'es';
  var keys=Object.keys(D).sort(function(x,y){return y.length-x.length});
  var isL=function(c){return c>='0'&&c<='9'||c.toLowerCase()!==c.toUpperCase()};
  var IDX=Object.create(null);
  keys.forEach(function(k){var c=k.charAt(0);(IDX[c]||(IDX[c]=[])).push(k)});
  function rep(s){
    var out='',i=0,n=s.length;
    while(i<n){
      var ch=s.charAt(i),ks=IDX[ch],hit=null;
      if(ks){
        for(var j=0;j<ks.length;j++){
          var k=ks[j];
          if(s.startsWith(k,i)){
            if(isL(k.charAt(0))&&i>0&&isL(s.charAt(i-1)))continue;
            var e=i+k.length;
            if(isL(k.charAt(k.length-1))&&e<n&&isL(s.charAt(e)))continue;
            hit=k;break;
          }
        }
      }
      if(hit){out+=D[hit];i+=hit.length}else{out+=ch;i++}
    }
    return out;
  }
  var cache=Object.create(null);
  function tr(s){
    if(!s||typeof s!=='string'||!/[A-Za-zÀ-ÿ]/.test(s))return s;
    var c=cache[s];if(c!==undefined)return c;
    var lead=s.match(/^\s*/)[0],trail=s.match(/\s*$/)[0],core=s.slice(lead.length,s.length-trail.length),out;
    if(D[core]!==undefined)out=lead+D[core]+trail;
    else out=rep(s);
    cache[s]=out;return out;
  }
  window.__tr=tr;
  var SKIP={SCRIPT:1,STYLE:1,TEXTAREA:1,NOSCRIPT:1};
  var done=new WeakMap();
  function txt(n){
    var p=n.parentNode;if(p&&SKIP[p.nodeName])return;
    var v=n.nodeValue;if(done.get(n)===v)return;
    var o=tr(v);if(o!==v){n.nodeValue=o}
    done.set(n,n.nodeValue);
  }
  var ATT=['placeholder','title','aria-label','alt'];
  function attrs(el){for(var i=0;i<ATT.length;i++){var a=ATT[i];if(el.hasAttribute(a)){var v=el.getAttribute(a),o=tr(v);if(o!==v)el.setAttribute(a,o)}}}
  function walk(n){
    if(n.nodeType===3){txt(n);return}
    if(n.nodeType!==1||SKIP[n.nodeName])return;
    if(n.hasAttribute('data-notr'))return;
    attrs(n);
    for(var c=n.firstChild;c;c=c.nextSibling)walk(c);
  }
  function start(){
    document.title=tr(document.title);
    walk(document.documentElement);
    var t0=Date.now(),spent=0,obs=new MutationObserver(function(ms){
      var a=Date.now();
      if(a-t0>1000){t0=a;spent=0}
      for(var i=0;i<ms.length;i++){
        var m=ms[i];
        if(m.type==='childList'){for(var j=0;j<m.addedNodes.length;j++)walk(m.addedNodes[j])}
        else if(m.type==='characterData')txt(m.target);
        else if(m.type==='attributes')attrs(m.target);
      }
      spent+=Date.now()-a;
      if(spent>500){obs.disconnect();window.__trOff=true;try{console.warn('Tradução automática pausada para não travar a página.')}catch(e){}}
    });
    obs.observe(document.documentElement,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:ATT});
  }
  ['alert','confirm','prompt'].forEach(function(f){var o=window[f];window[f]=function(m,d){return o.call(window,tr(String(m)),d)}});
  ['toLocaleDateString','toLocaleTimeString','toLocaleString'].forEach(function(m){var o=Date.prototype[m];Date.prototype[m]=function(l,opt){return o.call(this,l==='pt-BR'?LOC:l,opt)}});
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start);else start();
})();
